function renderProductCard(product,opts){const href=opts&&opts.storeSlug?`product.html?store=${encodeURIComponent(opts.storeSlug)}&product=${encodeURIComponent(product.productId)}`:"";const photoLink=inner=>href?`<a class="product-card-link" href="${escapeAttr(href)}" tabindex="-1">${inner}</a>`:inner;const drag=href?' draggable="false"':"";const options=product.variants.map(v=>`<option value="${v.variantId}" data-price="${v.price}">${escapeHtml(v.label)} — ${formatMoney(v.price)}</option>`).join("");const photos=productOwnPhotos(product);const n=photos.length;const media=n>1?`<div class="product-gallery-track">\n          ${photos.map((u,i)=>photoLink(`<img class="product-image" src="${escapeHtml(optimizedImageUrl(u,IMG_W.card))}"${srcsetAttr(u,IMG_SIZES_CARD)} alt="Photo ${i+1} of ${escapeHtml(product.name)}" loading="lazy" decoding="async"${drag}>`)).join("")}\n        </div>`:n===1?photoLink(`<img class="product-image" src="${escapeHtml(optimizedImageUrl(photos[0],IMG_W.card))}"${srcsetAttr(photos[0],IMG_SIZES_CARD)} alt="${escapeHtml(product.name)}" loading="lazy" decoding="async"${drag}>`):photoLink(`<div class="placeholder-swatch category-${escapeHtml(categoryIdOf(product.category))}" aria-hidden="true">${escapeHtml(initials(product.name))}</div>`);const thumbs=n>1?`<div class="product-gallery-thumbs">\n          ${photos.map((u,i)=>`<button type="button" class="product-gallery-thumb${i===0?" active":""}" data-index="${i}"><img src="${escapeHtml(optimizedImageUrl(u,IMG_W.thumb))}" alt="Photo ${i+1} of ${escapeHtml(product.name)}" loading="lazy" decoding="async"></button>`).join("")}\n        </div>`:"";const pid=escapeHtml(product.productId);const nameHtml=href?`<a class="product-card-link product-name-link" href="${escapeAttr(href)}">${escapeHtml(product.name)}</a>`:escapeHtml(product.name);const priceText=formatPriceLabel(product.variants);if(isBookingListing(product)){const availabilityBadge=product.available===false?'<span class="availability-badge availability-badge--unavailable">Booked today</span>':product.available===true?'<span class="availability-badge availability-badge--available">Available</span>':"";return`\n      <article class="product-card product-card--booking" data-product-id="${pid}">\n        ${media}\n        ${thumbs}\n        <div class="product-card-body">\n          <h3 class="product-name">${nameHtml} ${availabilityBadge}</h3>\n          <strong class="product-price">${priceText}</strong>\n          ${product.description?`<p class="product-desc">${escapeHtml(product.description)}</p>`:""}\n          ${productDetailsHtml(product)}\n          <div class="product-controls">\n            <label class="sr-only" for="variety-${pid}">Choose a rate for ${escapeHtml(product.name)}</label>\n            <select id="variety-${pid}" class="variety-select">${options}</select>\n          </div>\n          <div class="booking-dates-row">\n            <div class="booking-date-field">\n              <label class="booking-date-label" for="start-${pid}">Pick-up date</label>\n              <input id="start-${pid}" class="booking-start-input" type="date" aria-label="Pick-up date">\n            </div>\n            <div class="booking-date-field">\n              <label class="booking-date-label" for="end-${pid}">Return date</label>\n              <input id="end-${pid}" class="booking-end-input" type="date" aria-label="Return date">\n            </div>\n          </div>\n          <div class="booking-contact-fields">\n            <label class="sr-only" for="name-${pid}">Your name</label>\n            <input id="name-${pid}" class="booking-name-input" placeholder="Your name">\n            <label class="sr-only" for="phone-${pid}">Phone number</label>\n            <input id="phone-${pid}" class="booking-phone-input" placeholder="Phone number" inputmode="tel">\n            <label class="sr-only" for="notes-${pid}">Notes (optional)</label>\n            <textarea id="notes-${pid}" class="booking-notes-input" placeholder="Notes (optional)"></textarea>\n          </div>\n          <div class="product-actions">\n            <button type="button" class="btn btn-primary request-booking-btn" data-product-id="${pid}" data-product-name="${escapeHtml(product.name)}">\n              Request Booking\n            </button>\n          </div>\n          <p class="booking-request-status helper-text" id="booking-status-${pid}" role="status"></p>\n          <div class="booking-vendor-contact hidden" id="booking-contact-${pid}"></div>\n        </div>\n      </article>\n    `}if((product.productType==="options"||product.productType==="single")&&typeof OptionsUI!=="undefined"){const isOptions=product.productType==="options";const only=!isOptions?product.variants[0]:null;const soldOut=only&&only.stockQty!=null&&only.stockQty<=0;const singleStatus=only?`<p class="option-status" aria-live="polite">${soldOut?'<span class="option-stock option-stock--out">Sold out</span>':only.stockQty!=null&&only.stockQty<=5?`<span class="option-stock option-stock--low">Only ${only.stockQty} left</span>`:"In stock"}${only.sku?` · <span class="option-sku">SKU ${escapeHtml(only.sku)}</span>`:""}</p>`:"";return`\n    <article class="product-card product-card--options" data-product-id="${pid}">\n      <div class="pdp-gallery">${OptionsUI.galleryHtml(product,OptionsUI.galleryFor(product,{}))}</div>\n      <div class="product-card-body">\n        <h3 class="product-name">${nameHtml}</h3>\n        <strong class="product-price">${priceText}</strong>\n        ${product.description?`<p class="product-desc">${escapeHtml(product.description)}</p>`:""}\n          ${productDetailsHtml(product)}\n        ${isOptions?OptionsUI.pickerHtml(product):singleStatus}\n        <input type="hidden" id="variety-${pid}" class="variety-select" value="${only&&!soldOut?escapeHtml(only.variantId):""}">\n        <div class="product-actions">\n          <label class="sr-only" for="qty-${pid}">Quantity</label>\n          <input id="qty-${pid}" class="qty-input" type="number" min="1" value="1" inputmode="numeric"${only&&only.stockQty!=null&&only.stockQty>0?` max="${only.stockQty}"`:""}>\n          <button type="button" class="btn btn-primary add-to-cart-btn" data-product-id="${pid}" data-product-name="${escapeHtml(product.name)}"${isOptions||soldOut?" disabled":""} aria-describedby="${isOptions?"option-status-"+pid:""}">\n            Add to Cart\n          </button>\n        </div>\n      </div>\n    </article>\n  `}return`\n    <article class="product-card" data-product-id="${pid}">\n      ${media}\n      ${thumbs}\n      <div class="product-card-body">\n        <h3 class="product-name">${nameHtml}</h3>\n        <strong class="product-price">${priceText}</strong>\n        ${product.description?`<p class="product-desc">${escapeHtml(product.description)}</p>`:""}\n          ${productDetailsHtml(product)}\n        <div class="product-controls">\n          <label class="sr-only" for="variety-${pid}">Choose an option for ${escapeHtml(product.name)}</label>\n          <select id="variety-${pid}" class="variety-select">${options}</select>\n        </div>\n        <div class="product-actions">\n          <label class="sr-only" for="qty-${pid}">Quantity</label>\n          <input id="qty-${pid}" class="qty-input" type="number" min="1" value="1" inputmode="numeric">\n          <button type="button" class="btn btn-primary add-to-cart-btn" data-product-id="${pid}" data-product-name="${escapeHtml(product.name)}">\n            Add to Cart\n          </button>\n        </div>\n      </div>\n    </article>\n  `}